def sample_user():
    return {"name": "Ana", "role": "admin"}

def test_user_has_name():
    user = sample_user()
    assert user["name"] == "Ana"

def test_user_is_admin():
    user = sample_user()
    assert user["role"] == "admin"

for test in (test_user_has_name, test_user_is_admin):
    test()
    print(f"{test.__name__}: OK")
